export type Attachment = { name: string; size?: number; type?: string; url?: string };

/** A file to show inline and in the preview panel: generated by the assistant or attached by the user.
 *  Give `url` (http, blob: or data:) or `blob`. `versions` (oldest first) adds a version picker in the panel. */
export type FilePart = {
	type: 'file';
	id: string;
	name: string;
	mime: string;
	url?: string;
	blob?: Blob;
	size?: number;
	versions?: { label: string; url?: string; blob?: Blob }[];
};

export type TextPart = { type: 'text'; id?: string; text: string };

export type AskOption = {
	value: string;
	label: string;
	/** Emoji or short text shown before the label. */
	icon?: string;
	/** Image URL shown in the button. */
	image?: string;
	description?: string;
};

/** One question. `kind` picks the control; the comment gives the emitted value type. */
export type AskField =
	| {
			kind: 'choice'; // string, or string[] when multiple
			options: AskOption[];
			multiple?: boolean;
			display?: 'buttons' | 'radio' | 'checkbox' | 'select';
			min?: number;
			max?: number;
			/** Quiz: the correct value(s); the answer is then marked right or wrong. */
			correct?: string | string[];
	  }
	| { kind: 'text'; multiline?: boolean; placeholder?: string; pattern?: string; minLength?: number; maxLength?: number } // string
	| { kind: 'number'; min?: number; max?: number; step?: number } // number
	| { kind: 'slider'; min: number; max: number; step?: number } // number
	| { kind: 'rating'; max?: number } // number, 1..max (default 5)
	| { kind: 'date'; min?: string; max?: string } // 'YYYY-MM-DD'
	| { kind: 'file'; accept?: string; multiple?: boolean } // File[]
	| { kind: 'confirm'; confirmLabel?: string; cancelLabel?: string }; // boolean

export type AskStep = AskField & { id: string; prompt: string; help?: string; required?: boolean };

/** A question, or a multi-step wizard/quiz, asked by the assistant. One step = one question, no progress bar.
 *  The answer goes to `onAction({ messageId, partId, value })`: the step's value for one step, else `{ [stepId]: value }`.
 *  Store it back as `answer` to keep the part answered (disabled) across reloads. */
export type AskPart = { type: 'ask'; id: string; title?: string; steps: AskStep[]; submitLabel?: string; answer?: unknown };

/** A tool/function call made by the assistant, shown as a collapsible card. */
export type ToolPart = { type: 'tool'; id: string; name: string; args?: unknown; status: 'running' | 'done' | 'error'; result?: unknown };

export type MessagePart = TextPart | FilePart | AskPart | ToolPart;

/** A source cited as [n] in the Markdown (n is 1-based into `sources`). */
export type Source = { title: string; url: string; snippet?: string };

export type ChatAction = { messageId: string; partId: string; value: unknown };

export type ChatMessage = {
	id: string;
	role: 'user' | 'assistant' | 'system';
	/** Markdown for assistant messages, plain text for user messages. */
	content: string;
	/** Rendered after `content`, in order. */
	parts?: MessagePart[];
	attachments?: Attachment[];
	/** Shown under the message, with a retry button on assistant messages. */
	error?: string;
	/** Model reasoning, shown in a collapsible "Thinking" block above the answer. */
	reasoning?: string;
	/** Seconds spent reasoning, for the "Thought for Ns" summary. */
	reasoningTime?: number;
	sources?: Source[];
	/** Follow-up chips under the last assistant message; a click sends the text. */
	followUps?: string[];
	feedback?: 'up' | 'down' | null;
	/** All versions of this message (retry/edit branches), managed with branch() and switchVersion(). */
	versions?: MessageVersion[];
	versionIndex?: number;
};

export type MessageVersion = Omit<ChatMessage, 'versions' | 'versionIndex'> & { tail: ChatMessage[] };

